import {BrowserRouter as Router, Routes, Route} from "react-router-dom";
import Drawing from "./components/Drawing";
import Placeholder from "./components/Placeholder"
import { projectId } from "./Constants";
import Main from "./pages/Main";
import { syncDrawings } from "./database/sync";
import { useEffect } from "react";

function App() {

  useEffect(() => {
    // Se ejecuta una sola vez al cargar la app
    syncDrawings().then(() => console.log("✅ syncDrawings terminado")).catch(err => console.log("❌ Error en syncDrawings", err));
  }, []);

  return (
    <Router basename={`${projectId}/application`}>
      <Routes>
        <Route path='/' element={<Main drawing={<Placeholder/>} /> }/>
        <Route path='/:path/*' element={<Main drawing={<Drawing/>} />}/>
      </Routes>
    </Router>
  );
}

export default App;
