import React from "react";
import "../Css/processing.css"; // CSS separado para el diseño

const ProcessingOverlay = ({ message = "Processing Data...", visible = false }) => {
  if (!visible) return null; // Si no está activo, no renderiza nada

  return (
    <div className="processing-overlay">
      <div className="processing-content">
        <div className="spinner-border text-light" style={{ width: "3rem", height: "3rem" }}></div>
        <h4 className="mt-3 text-white">{message}</h4>
      </div>
    </div>
  );
};

export default ProcessingOverlay;
