import Dexie from 'dexie';

export const db = new Dexie('qto');
db.version(11).stores({
   drawings: '++id, &path, scale, area, updated_at',
   course_band: '++id, name, band_material, band_elevation, fill_material, rebar_material, rebar_overlap, updated_at',
   line_Takeoff: '++id, takeoff_name, lineTemplate, updated_at'
}).upgrade(tx => {
   // Migración: aseguramos que todos los registros tengan updated_at
   return Promise.all([
      tx.table('drawings').toCollection().modify(record => {
         if (!record.updated_at) {
            record.updated_at = new Date().toISOString();
         }
      }),
      tx.table('course_band').toCollection().modify(record => {
         if (!record.updated_at) {
            record.updated_at = new Date().toISOString();
         }
      }),
      tx.table('line_Takeoff').toCollection().modify(record => {
         if (!record.updated_at) {
            record.updated_at = new Date().toISOString();
         }
      })
   ]);
});