import { useRef, useEffect, useState } from "react";
import { useLocation } from "react-router-dom";
import { routes } from "../Constants";
import useSignal from "../hooks/signals";
import { MapInteractionCSS } from "react-map-interaction";
import FileLoader from "./FileLoader";
import SVGBoard from "./SVGBoard";


// ==========================
//   RENDER PNG/JPG TO CANVAS
// ==========================
async function renderImageToCanvas(url, scaleFactor = 1) {
  const img = new Image();
  img.crossOrigin = "anonymous";

  return new Promise((resolve) => {
    img.onload = () => {
      const canvas = document.createElement("canvas");
      const ctx = canvas.getContext("2d");

      canvas.width = img.width * scaleFactor;
      canvas.height = img.height * scaleFactor;

      ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
      resolve(canvas);
    };
    img.src = url;
  });
}


// ==========================
//      RENDER SVG TO CANVAS
// ==========================
async function renderSVGToCanvas(svgText, scaleFactor = 4) {
  const temp = document.createElement("div");
  temp.innerHTML = svgText;

  const svg = temp.querySelector("svg");
  if (!svg) return null;

  const width = parseInt(svg.getAttribute("width"), 10);
  const height = parseInt(svg.getAttribute("height"), 10);

  const canvas = document.createElement("canvas");
  const ctx = canvas.getContext("2d");

  canvas.width = width * scaleFactor;
  canvas.height = height * scaleFactor;

  ctx.fillStyle = "white";
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  const img = new Image();
  return new Promise((resolve) => {
    img.onload = () => {
      ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
      resolve(canvas);
    };
    img.src =
      "data:image/svg+xml;charset=utf-8," + encodeURIComponent(svgText);
  });
}



function Drawing() {
  const containerRef = useRef();
  const { pathname } = useLocation();
  const [rotate, setRotate] = useState(0);
  const [loading, setLoading] = useState(false);
  const signal = useSignal();

  const [transform, setTransform] = useState({
    scale: 0.01,
    translation: { x: 12, y: 155.898 },
  });

  const MIN_SCALE = 0.01;
  const MAX_SCALE = 0.5;


  // ==========================
  //       ROTATE SIGNAL
  // ==========================
  useEffect(() => {
    let callBack = () => setRotate((a) => a + 90);

    signal.listen("rotate", callBack);
    return () => signal.unsubscribe("rotate", callBack);
  }, []);



  // ============================================================
  //     *** LOADER PRINCIPAL (SVG + PNG + JPG, NO PDF) ***
  // ============================================================
  useEffect(() => {
    (async () => {
      try {
        signal.emit("tab.active", { pathname });
      } catch (e) {}

      setLoading(true);

      const fullUrl = routes.public + pathname;
      const lower = fullUrl.toLowerCase();
      let canvas = null;

      // ---- PNG / JPG ----
      if (
        lower.endsWith(".png") ||
        lower.endsWith(".jpg") ||
        lower.endsWith(".jpeg")
      ) {
        canvas = await renderImageToCanvas(fullUrl, 1);
      }

      // ---- SVG ----
      else if (lower.endsWith(".svg")) {
        const response = await fetch(fullUrl);
        const svgText = await response.text();
        canvas = await renderSVGToCanvas(svgText, 4);
      }

      // ---- PDF (NO SE DEBE USAR AQUÍ → FileView ya genera PNGs) ----
      else if (lower.endsWith(".pdf")) {
        console.warn(
          "Intento de abrir PDF en Drawing.js — NO permitido. Use PNG generado."
        );
        setLoading(false);
        return;
      }

      // ---- Insertar CANVAS ----
      if (canvas && containerRef.current) {
        containerRef.current.appendChild(canvas);
      }

      setLoading(false);
    })();

    // limpieza
    return () => {
      const allCanvas = document.querySelectorAll("canvas");
      allCanvas.forEach((c) => c.remove());
    };
  }, [pathname]);



  // ==========================
  //         RENDER UI
  // ==========================
  return (
    <>
      <div className={`drawing-board__container ${loading ? "hidden" : ""}`}>
        <MapInteractionCSS
          minScale={MIN_SCALE}
          maxScale={MAX_SCALE}
          value={transform}
          onChange={setTransform}
          showControls={true}
        >
          <div
            className="drawing-board"
            ref={containerRef}
            style={{ transform: `rotate(${rotate}deg)` }}
          >
            <SVGBoard transform={transform} />
          </div>
        </MapInteractionCSS>
      </div>

      {loading ? <FileLoader /> : <></>}
    </>
  );
}

export default Drawing;
