import { useEffect, useState } from "react";
import { createPortal } from "react-dom";
import Draggable from "react-draggable";
import { Document, Page, pdfjs } from "react-pdf";
import { routes, projectId } from "../Constants";
import { toast } from "react-toastify";
import useSignal from "../hooks/signals";
import { createWorker } from "tesseract.js";
import axios from "axios";
import "../pages_css.css";

// 🧠 Configuración del worker PDF.js
pdfjs.GlobalWorkerOptions.workerSrc = `${process.env.PUBLIC_URL}/pdf.worker.mjs`;

function PdfPreviewPopup({ setDisplay, file }) {
  const signal = useSignal();
  const [numPages, setNumPages] = useState(0);
  const [selectedPages, setSelectedPages] = useState([]);
  const [selectAll, setSelectAll] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [pageMeta, setPageMeta] = useState([]);
  const [scanning, setScanning] = useState(false);

  const onDocumentLoadSuccess = ({ numPages }) => {
    setNumPages(numPages);
  };

  const itemsToLines = (items) => {
    const lines = [];
    let currentY = null;
    let buffer = [];

    for (const it of items) {
      const y = Math.round(it.transform?.[5] ?? 0);

      if (currentY === null) {
        currentY = y;
        buffer.push(it.str);
      } else if (Math.abs(y - currentY) <= 2) {
        buffer.push(it.str);
      } else {
        lines.push(buffer.join(" ").trim());
        buffer = [it.str];
        currentY = y;
      }
    }

    if (buffer.length) lines.push(buffer.join(" ").trim());
    return lines;
  };

  const togglePage = (num) => {
    setSelectedPages((prev) =>
      prev.includes(num)
        ? prev.filter((n) => n !== num)
        : [...prev, num]
    );
  };

  const handleSelectAll = () => {
    if (selectAll) {
      setSelectedPages([]);
      setSelectAll(false);
    } else {
      const all = Array.from({ length: numPages }, (_, i) => i + 1);
      setSelectedPages(all);
      setSelectAll(true);
    }
  };

  const handleUpload = async () => {
    if (selectedPages.length === 0) {
      toast.warning("Selecciona al menos una página antes de subir.");
      return;
    }

    try {
      setUploading(true);
      const formData = new FormData();
      formData.append("file", file);
      formData.append("pages", JSON.stringify(selectedPages));
      formData.append("project_id", projectId);

      await axios.post(routes.upload, formData, {
        headers: { Authorization: `Bearer ${routes.__token}` },
      });

      toast.success("✅ Archivo subido correctamente");
      setDisplay(false);
      signal.emit("refresh");
    } catch (error) {
      console.error("❌ Error al subir PDF:", error);
      toast.error("Error al subir el PDF.");
    } finally {
      setUploading(false);
    }
  };

  // ===============================================================
  // 🧠 IA VISION: convertir blob a base64 (requerido por OpenAI)
  // ===============================================================
  const blobToBase64 = (blob) =>
    new Promise((resolve) => {
      const reader = new FileReader();
      reader.onloadend = () => resolve(reader.result.split(",")[1]);
      reader.readAsDataURL(blob);
    });

  // ===============================================================
  // 🧠 IA VISION: detectar código arquitectónico
  // ===============================================================
  const detectCodeAI = async (blob) => {
    try {
      const base64 = await blobToBase64(blob);

      const response = await fetch("https://api.openai.com/v1/chat/completions", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${routes.openai_token}`,
        },
        body: JSON.stringify({
          model: "gpt-5-nano",
          messages: [
            {
              role: "system",
              content:
                "Extrae únicamente el código arquitectónico (ejemplo: AG-2, X-110, XS-210) puede tener - o algun signo ortigráfico o no tener . Devuelve solo el código."
            },
            {
              role: "user",
              content: [
                { type: "text", text: "Detecta el código de plano:" },
                { type: "image_url", image_url: {url: `data:image/png;base64,${base64}`} }
              ]
            }
          ]
        }),
      });

      const result = await response.json();
      const text = result?.choices?.[0]?.message?.content?.trim();

      if (!text) return null;

      // Regex para limpiar respuestas como "El código es XS-110"
      const match = text.match(/[A-Z]{1,4}[-–.]?\d{1,4}/i);
      return text;

    } catch (err) {
      console.error("ERROR IA:", err);
      return null;
    }
  };

  // ======================================
  // Escaneo de códigos en cada página
  // ======================================
  useEffect(() => {
    let cancelled = false;

    const scanPdf = async () => {
      if (!file) return;

      setScanning(true);
      const meta = [];

      try {
        let pdfData = null;

        if (file instanceof File || file instanceof Blob) {
          pdfData = await file.arrayBuffer();
        } else if (file?.url) {
          pdfData = file.url;
        }

        if (!pdfData) {
          console.error("PDF vacío o inválido:", file);
          return;
        }

        const task = pdfjs.getDocument(
          pdfData instanceof ArrayBuffer ? { data: pdfData } : { url: pdfData }
        );
        const pdf = await task.promise;

        for (let pageNum = 1; pageNum <= pdf.numPages; pageNum++) {
          if (cancelled) return;

          const page = await pdf.getPage(pageNum);
          const viewport = page.getViewport({ scale: 2 });

          // Render página completa a canvas
          const canvas = document.createElement("canvas");
          const ctx = canvas.getContext("2d");
          canvas.width = viewport.width;
          canvas.height = viewport.height;

          await page.render({ canvasContext: ctx, viewport }).promise;

          const W = canvas.width;
          const H = canvas.height;

          // --- Q4 DEL TITLE BLOCK ---
          let qWidth = Math.floor(W * 0.20);
          let qHeight = Math.floor(H * 0.15);
          let qX = Math.floor(W * 0.88);
          let qY = Math.floor(H * 0.85);

          if (qX < 0) qX = 0;
          if (qY < 0) qY = 0;
          if (qX + qWidth > W) qWidth = W - qX;
          if (qY + qHeight > H) qHeight = H - qY;

          const crop = ctx.getImageData(qX, qY, qWidth, qHeight);

          // --- Canvas temporal ---
          const tempCanvas = document.createElement("canvas");
          tempCanvas.width = qWidth;
          tempCanvas.height = qHeight;
          const tctx = tempCanvas.getContext("2d");
          tctx.putImageData(crop, 0, 0);

          const blob = await new Promise((resolve) =>
            tempCanvas.toBlob(resolve, "image/png")
          );

          // ===============================================
          // 🔥 OCR NORMAL (como ya lo tenías)
          // ===============================================
          const worker = await createWorker("eng");

          const { data: { text } } = await worker.recognize(blob);
          await worker.terminate();

          const regex = /\b([A-Z]{1,4}[-.]?\d{1,4})\b/g;
          let codes = [];
          //let m;

          /*while ((m = regex.exec(text)) !== null) {
            codes.push(m[1]);
          }

          codes = [...new Set(codes)];

          console.log("OCR RESULT PAGE", pageNum, "→", codes);*/

          // ====================================================
          // 🔥 IA VISION FALLBACK — SOLO SI OCR NO ENCONTRÓ NADA
          // ====================================================
          if (codes.length === 0) {
            console.log("⚠ OCR no encontró código → usando IA Vision...");

            const aiCode = await detectCodeAI(blob);

            if (aiCode) {
              console.log("IA DETECTÓ →", aiCode);
              codes.push(aiCode);
            }
          }

          setPageMeta(prev =>
            [
              ...prev.filter(p => p.page !== pageNum),
              { page: pageNum, codes }
            ]
          );
        }

        //if (!cancelled) setPageMeta(meta);
      } catch (err) {
        console.error("Error leyendo PDF:", err);
      } finally {
        if (!cancelled) setScanning(false);
      }
    };

    scanPdf();
    return () => (cancelled = true);
  }, [file]);

  const getCodesFor = (page) =>
    pageMeta.find((x) => x.page === page)?.codes ?? [];

  // ======================================
  // RENDER POPUP (NO SE MODIFICÓ NADA)
  // ======================================
  return createPortal(
    <Draggable handle=".modal-header">
      <div className="popup__count">
        <div className="modal-header">
          Vista previa del PDF
          <span
            className="close-btn"
            onClick={() => setDisplay(false)}
            style={{ cursor: "pointer" }}
          >
            &times;
          </span>
        </div>

        <div
          className="modal-body"
          style={{
            background: "#f3f3f3",
            maxHeight: "80vh",
            overflowY: "auto",
          }}
        >
          {file ? (
            <Document
              file={file}
              onLoadSuccess={onDocumentLoadSuccess}
              loading={<p>Cargando PDF...</p>}
              onLoadError={(err) => console.error("Error al cargar PDF:", err)}
            >
              <div
                style={{
                  display: "flex",
                  flexWrap: "wrap",
                  gap: "10px",
                  justifyContent: "center",
                }}
              >
                {Array.from(new Array(numPages), (el, index) => (
                  <div
                    key={`page_${index + 1}`}
                    style={{
                      border: selectedPages.includes(index + 1)
                        ? "3px solid #0d6efd"
                        : "1px solid #ccc",
                      borderRadius: "6px",
                      background: "#fff",
                      padding: "8px",
                      textAlign: "center",
                      width: "140px",
                    }}
                  >
                    <Page
                      pageNumber={index + 1}
                      width={120}
                      renderTextLayer={false}
                      renderAnnotationLayer={false}
                    />

                    <div style={{ marginTop: "6px" }}>
                      <label style={{ fontSize: "12px" }}>
                        <input
                          type="checkbox"
                          checked={selectedPages.includes(index + 1)}
                          onChange={() => togglePage(index + 1)}
                          style={{ marginRight: "4px" }}
                        />
                        Página {index + 1}
                      </label>
                    </div>

                    {(() => {
                      const pageNumber = index + 1;
                      const codes = getCodesFor(pageNumber);

                      return codes.length > 0 ? (
                        <div
                          style={{
                            marginTop: 6,
                            fontSize: 11,
                            textAlign: "left",
                            background: "#f8f9fa",
                            border: "1px dashed #ced4da",
                            borderRadius: 6,
                            padding: "6px",
                            maxHeight: 90,
                            overflowY: "auto",
                          }}
                        >
                          <strong>{file?.name}</strong>
                          {codes.map((c, i) => (
                            <div key={i}>— {c}</div>
                          ))}
                        </div>
                      ) : (
                        <div
                          style={{
                            marginTop: 6,
                            fontSize: 11,
                            color: "#6c757d",
                          }}
                        >
                          (Sin código detectado)
                        </div>
                      );
                    })()}
                  </div>
                ))}
              </div>
            </Document>
          ) : (
            <p>No se ha cargado ningún archivo PDF.</p>
          )}
        </div>

        <div
          className="modal-footer"
          style={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            background: "#f1f1f1",
            padding: "10px 15px",
            borderTop: "1px solid #ccc",
          }}
        >
          <label style={{ margin: 0, fontWeight: "bold" }}>
            <input
              type="checkbox"
              checked={selectAll}
              onChange={handleSelectAll}
              style={{ marginRight: "6px" }}
            />
            Seleccionar todas
          </label>

          <div>
            <button
              className="btn btn-secondary me-2"
              onClick={() => setDisplay(false)}
              disabled={uploading}
            >
              Cancelar
            </button>
            <button
              className="btn btn-primary"
              onClick={handleUpload}
              disabled={uploading}
            >
              {uploading ? "Subiendo..." : "Subir páginas seleccionadas"}
            </button>
          </div>
        </div>
      </div>
    </Draggable>,
    document.querySelector("#root")
  );
}

export default PdfPreviewPopup;
