import { useState, useEffect } from "react";
import { Link } from "react-router-dom";
import FileContext from "./FileContext";
import { routes } from "../Constants";
import "../proposalpopup.css";
import ProjectMeasurement from "./ProjectMeasurement";

/* ============================================================
   UTILS
============================================================ */
function fileName(url) {
    let arr = url.split("/");
    return arr[arr.length - 1].replace(".svg", "").replace(".pdf", "");
}

function dataURLtoBlob(dataURL) {
    const arr = dataURL.split(",");
    const mime = arr[0].match(/:(.*?);/)[1];
    const bstr = atob(arr[1]);
    let n = bstr.length;
    const u8arr = new Uint8Array(n);
    while (n--) u8arr[n] = bstr.charCodeAt(n);
    return new Blob([u8arr], { type: mime });
}

/* ============================================================
   MAIN COMPONENT
============================================================ */
function FileView({ plans }) {

    const [context, setContext] = useState(null);
    const [isProjectMeasurementOpen, setIsProjectMeasurementOpen] = useState(false);

    const [previewImages, setPreviewImages] = useState({});

    // 👇 NUEVO → estado de progreso por archivo
    const [processingState, setProcessingState] = useState({});

    /* ============================================================
        Convert FULL PDF → PNG multipágina
    ============================================================ */
    async function generatePNGs(plan) {
        const pdfUrl = `${routes.webUrl}/${encodeURI(plan)}`;

        const loadingTask = window.pdfjsLib.getDocument(pdfUrl);
        const pdf = await loadingTask.promise;

        const pages = [];

        for (let pageNum = 1; pageNum <= pdf.numPages; pageNum++) {
            const page = await pdf.getPage(pageNum);
            const viewport = page.getViewport({ scale: 3.0 });

            const canvas = document.createElement("canvas");
            const ctx = canvas.getContext("2d");

            canvas.width = viewport.width;
            canvas.height = viewport.height;

            await page.render({ canvasContext: ctx, viewport }).promise;

            pages.push({
                num: pageNum,
                base64: canvas.toDataURL("image/png")
            });
        }

        return pages;
    }

    /* ============================================================
        Upload PNG
    ============================================================ */
    async function uploadPNG(base64, fileName, projectId) {

        const blob = dataURLtoBlob(base64);

        const formData = new FormData();
        formData.append("image", blob, fileName);
        formData.append("file_name", fileName);
        formData.append("project_id", projectId);

        await fetch(`${routes.webUrl}/api/save-plan-image`, {
            method: "POST",
            headers: {
                Authorization: `Bearer ${routes.__token}`,
            },
            body: formData,
        });
    }

    /* ============================================================
        Obtener previews → ahora con PROGRESO
    ============================================================ */
    async function getPreview(plan, onPageReady, onProgress) {

        let fixedPlan = plan.startsWith("uploads/")
            ? plan
            : `uploads/${plan}`;

        fixedPlan = fixedPlan.replace(/^uploads\/uploads\//, "uploads/");

        const lower = fixedPlan.toLowerCase();
        if (lower.endsWith(".png") || lower.endsWith(".svg")) {
            onProgress(plan, 1, 1, true);
            onPageReady(plan, []);
            return;
        }

        const parts = fixedPlan.split("/");
        const projectFolder = parts[2];
        const projectId = projectFolder.replace("project", "");
        const baseFileName = parts[3];

        const isPDF = baseFileName.toLowerCase().endsWith(".pdf");

        if (!isPDF) {
            onProgress(plan, 1, 1, true);
            onPageReady(plan, [`${routes.webUrl}/${fixedPlan}`]);
            return;
        }

        const prefix = baseFileName.replace(".pdf", "");

        // ======================================================
        // 1) 🟦 CONSULTAR MINIATURAS EXISTENTES EN EL SERVIDOR
        // ======================================================
        const listUrl = `${routes.webUrl}/api/list-plan-images?project=${projectId}&prefix=${prefix}`;

        let existing = [];
        try {
            const resp = await fetch(listUrl);
            existing = await resp.json(); 
            // Debe regresar: ["...page-1.png", "...page-2.png"]
        } catch (e) {
            console.warn("No se pudo listar miniaturas → usando fallback");
        }

        // Si YA EXISTEN TODAS, no generar nada
        if (existing.length > 0) {
            existing.forEach(url => onPageReady(plan, `${routes.webUrl}/${url}`));
            onProgress(plan, existing.length, existing.length, true);
            return;
        }

        // ======================================================
        // 2) 🟩 NO EXISTEN → ahora sí generamos miniaturas
        // ======================================================
        const pages = await generatePNGs(fixedPlan);
        const totalPages = pages.length;
        let currentPage = 0;

        for (const p of pages) {

            currentPage++;
            onProgress(plan, currentPage, totalPages, false);

            const pngName = `${prefix}-page-${p.num}.png`;
            const pngPath = `uploads/projects/${projectFolder}/${pngName}`;
            const fullPNG = `${routes.webUrl}/${pngPath}`;

            const exists = await fetch(fullPNG, { method: "HEAD" })
                .then(r => r.ok)
                .catch(() => false);

            if (!exists) {
                await uploadPNG(p.base64, pngName, projectId);
            }

            onPageReady(plan, fullPNG);
        }

        onProgress(plan, totalPages, totalPages, true);
    }

    /* ============================================================
        Cargar Previews de todos los planes
    ============================================================ */
    useEffect(() => {
        plans.forEach(async (plan) => {

            setProcessingState(prev => ({
                ...prev,
                [plan]: { total: 1, current: 0, done: false, flash: false }
            }));

            // limpiar previews
            setPreviewImages(prev => ({
                ...prev,
                [plan]: []
            }));

            await getPreview(
                plan,

                // ⬅ Añadir miniatura conforme se genera
                (currentPlan, newPageUrl) => {
                    if (Array.isArray(newPageUrl)) {
                        setPreviewImages(prev => ({
                            ...prev,
                            [currentPlan]: newPageUrl
                        }));
                        return;
                    }

                    setPreviewImages(prev => ({
                        ...prev,
                        [currentPlan]: [...(prev[currentPlan] || []), newPageUrl]
                    }));
                },

                // ⬅ Progreso
                (currentPlan, current, total, done) => {
                    setProcessingState(prev => ({
                        ...prev,
                        [currentPlan]: {
                            current,
                            total,
                            done,
                            flash: done ? true : prev[currentPlan]?.flash
                        }
                    }));

                    // quitar parpadeo después de 1 segundo
                    if (done) {
                        setTimeout(() => {
                            setProcessingState(prev => ({
                                ...prev,
                                [currentPlan]: {
                                    ...prev[currentPlan],
                                    flash: false
                                }
                            }));
                        }, 1000);
                    }
                }
            );
        });
    }, [plans]);

    /* ============================================================
        CONTEXT MENU
    ============================================================ */
    const handleContext = (e, plan) => {
        e.preventDefault();
        setContext({
            x: e.clientX,
            y: e.clientY,
            plan,
        });
    };

    const toggleProjectMeasurement = () =>
        setIsProjectMeasurementOpen(!isProjectMeasurementOpen);

    /* ============================================================
        RENDER
    ============================================================ */
    return (
        <>
            <button
                className="text-black text-14 d-inline-block return-projects-btn"
                onClick={() => (window.location.href = `${routes.webUrl}/project`)}
            >
                Return to Project list
            </button>

            <button
                className="text-black text-14 d-inline-block measurement-btn"
                onClick={toggleProjectMeasurement}
            >
                Open Project Measurement
            </button>

            {isProjectMeasurementOpen && <ProjectMeasurement plans={plans} />}

            <details className="tool__box" open>
                <summary>
                    <div className="tool__box-header">
                        <i className="fa fa-folder"></i> Plans and Documents
                    </div>
                </summary>

                {plans.map((plan) => {

                    const pages = previewImages[plan] || [];
                    const prog = processingState[plan] || {};

                    let fixedPlan = plan.startsWith("uploads/")
                        ? plan
                        : `uploads/${plan}`;

                    fixedPlan = fixedPlan.replace(/^uploads\/uploads\//, "uploads/");

                    const parts = fixedPlan.split("/");
                    const projectFolder = parts[2];

                    return pages.map((previewUrl, pgIndex) => {

                        const pngName = previewUrl.split("/").pop();
                        const viewerURL = `/projects/${projectFolder}/${pngName}`;

                        const isDone = prog.done;
                        const isFlashing = prog.flash;

                        return (
                            <Link
                                key={plan + "-" + pgIndex}
                                to={viewerURL}
                                onContextMenu={(e) => handleContext(e, plan)}
                                className="file__view d-flex flex-column align-items-center justify-content-center text-center mb-3 p-2 rounded"
                            >
                                <div
                                    className={
                                        "file-thumb mb-2 border d-flex align-items-center justify-content-center position-relative " +
                                        (isFlashing ? "border-flash" : "")
                                    }
                                    style={{
                                        width: "130px",
                                        height: "130px",
                                        overflow: "hidden",
                                        borderRadius: "8px",
                                        backgroundColor: "#f8f9fa",
                                        boxShadow: "0 2px 6px rgba(0,0,0,0.15)",
                                        border: isDone
                                            ? "3px solid #0d6efd"
                                            : "2px dashed #aaa",
                                    }}
                                >
                                    {!isDone && pgIndex === 0 && (
                                        <div
                                            className="spinner-border text-primary position-absolute"
                                            style={{ width: "30px", height: "30px" }}
                                        ></div>
                                    )}

                                    <img
                                        src={previewUrl}
                                        alt={pngName}
                                        style={{
                                            maxWidth: "95%",
                                            maxHeight: "95%",
                                            objectFit: "contain",
                                            opacity: isDone ? 1 : 0.4,
                                        }}
                                    />
                                </div>

                                <div className="file-info text-center">
                                    <i className="fa fa-file-text-o text-secondary me-2"></i>
                                    <span style={{ fontSize: "14px" }}>
                                        {fileName(plan)} — Page {pgIndex + 1}
                                    </span>
                                </div>

                                {!isDone && (
                                    <div className="text-muted" style={{ fontSize: "12px" }}>
                                        Procesando {prog.current} / {prog.total} páginas…
                                    </div>
                                )}
                            </Link>
                        );
                    });
                })}
            </details>

            {context && <FileContext details={context} />}
        </>
    );
}

export default FileView;
