import { useEffect, useState } from "react";
import { createPortal } from "react-dom";
import Draggable from "react-draggable";
import { routes } from "../Constants";
import { toast } from "react-toastify";
import { projectId } from "../Constants";
import { db } from "../database/db";
import ProcessingOverlay from "./ProcessingOverlay";
import useSignal from "../hooks/signals";

function PerimeterPopup({ setDisplay, perimeterData, takeoff=null }) {
  //const [PerimeterValue1, setPerimeterValue] = useState(takeoff?.perimetro ?? "");
  const signal = useSignal();
  const [formDataPerimeter, setFormDataPerimeter] = useState({
    name: "",  // Takeoff Name
    trade: "", // Select Trade
    perimeterFields: [{ perimeter:takeoff?.perimetro ?? "", material: "", materialQty: "", totalLf: "", totalUnits: "" }]
  });

  const [wallMaterials, setWallMaterials] = useState([]);
  const [trade, setTrade] = useState([]);
  const [templates, setTemplates] = useState([]);
  const [loading, setLoading] = useState(true);
  const [loadingMesagge, setLoadingMesagge] = useState([""]);

  const toastOptions = {
    position: "top-right",
    autoClose: 5000,
    hideProgressBar: false,
    closeOnClick: true,
    pauseOnHover: true,
    draggable: true,
    progress: 0,
  };



  // Set initial data when popup is opened
  /*useEffect(() => {
    if (perimeterData) {
      let parsedData = { ...perimeterData };

      // 🔹 Si trade viene como string JSON, parsearlo
      if (parsedData.trade && typeof parsedData.trade === "string") {
        try {
          parsedData.trade = JSON.parse(parsedData.trade);
        } catch (e) {
          console.warn("Error parsing trade:", e, parsedData.trade);
        }
      }

      // 🔹 Parsear cada material en perimeterFields
      if (Array.isArray(parsedData.perimeterFields)) {
        parsedData.perimeterFields = parsedData.perimeterFields.map(f => {
          let field = { ...f };
          if (field.material && typeof field.material === "string") {
            try {
              field.material = JSON.parse(field.material);
            } catch (e) {
              console.warn("Error parsing material:", e, field.material);
            }
          }
          return field;
        });
      }

      setFormDataPerimeter(prev => ({
        ...prev,
        ...parsedData
      }));
    }
  }, [perimeterData]);*/

  useEffect(() => {
    const fetchTemplates = async () => {
      try {
        setLoading(true);
        setLoadingMesagge("Processing templates...");
        const response = await fetch(
          `${routes.templates}?type_template=perimeter`,
          {
            method: "GET",
            headers: { Authorization: `Bearer ${routes.__token}` },
          }
        );
        const data = await response.json();
        setTemplates(data.template || []);
      } catch (error) {
        console.error("Error cargando templates:", error);
        toast.error("Error loading templates");
      } finally {
        setLoading(false); // ocultar overlay
      }
    };
    fetchTemplates();
  }, []);

  const set_line_template = (e) => {
    const { name, value } = e.target;
    const template = JSON.parse(e.target.value);
    /*setFormDataPerimeter({
      ...formDataPerimeter,
      [name]: value,
    });*/
    const json = JSON.parse(value);
    const current_selected_name = takeoff?.name ?? null;
    const current_selected_perimeter = takeoff?.perimetro ?? null;
    var local_db = JSON.parse(json.local_db)
    
    if (json != null) {

      if (current_selected_name) {
        local_db.name = current_selected_name;
        //document.getElementById('wall_length').readOnly = false;
      }

      if (current_selected_perimeter) {
        local_db.perimeter = current_selected_perimeter;
        //document.getElementById('wall_length').readOnly = false;
      }

      if (Array.isArray(local_db.perimeterFields)) {
        local_db.perimeterFields = local_db.perimeterFields.map((f) => ({
          ...f,
          perimeter: current_selected_perimeter || f.perimeter || "",
        }));
      }
    }
    setFormDataPerimeter(local_db);
    CalculateData(local_db);
  };

  const handleInputBlur = (event) => {
    const { name, value } = event.target;
     // Llama a la función CalculateData si es uno de esos campos
     CalculateData({
      ...formDataPerimeter,
      [name]: value,
    });
  }
  const handleInputChange = (event) => {
    const { name, value } = event.target;

    console.log("name", name);
    console.log("value", value);

    // Verifica si el campo pertenece a los campos de nivel superior como "Takeoff Name" y "Trade"
    if (name === "name") {
      // Actualiza los campos de nivel superior sin necesidad de procesar índices
      setFormDataPerimeter({
        ...formDataPerimeter,
        [name]: value,
      });
    }
    if (name === "trade") {
      CalculateData({
        ...formDataPerimeter,
        [name]: value,
      });
      return;
    }
    
    // Si el nombre es del tipo perimeterFields[0][perimeter], procesarlo como tal
    const match = name ? name.match(/\[(\d+)\]\[(\w+)\]/) : null;
    const index = match ? parseInt(match[1], 10) : null;
    const fieldName = match ? match[2] : null;

    // Verifica si no se pudo extraer un índice o un campo de propiedad
    if (index === null || fieldName === null) {
      console.warn(`Formato de nombre incorrecto o falta: ${name}`);
      return; // Si no es un campo válido, no continúes
    }
    console.log("index " + index);
    console.log("fieldName " + fieldName);
    // Actualiza el array de los perimeterFields con el campo correspondiente
    const updatedFields = [...formDataPerimeter.perimeterFields];
    if (updatedFields[index]) {
      updatedFields[index][fieldName] = value;
    }

    // Actualiza formDataPerimeter con los cambios
    const updatedFormData = {
      ...formDataPerimeter,
      perimeterFields: updatedFields,
    };

    if (fieldName === "material" ) {
      CalculateData(updatedFormData);
    }

    setFormDataPerimeter(updatedFormData);

     
  };

  useEffect(() => {
    (async () => {
      let updatedFormData = { ...(perimeterData ?? formDataPerimeter) };

      if (takeoff?.lineTemplate) {
        try {
          const parsedTemplate = 
            typeof takeoff.lineTemplate === "string"
              ? JSON.parse(takeoff.lineTemplate)
              : takeoff.lineTemplate;

          // Mezcla el contenido del template (especialmente local_db)
          if (parsedTemplate.local_db) {
            const parsedLocalDb = JSON.parse(parsedTemplate.local_db);
            updatedFormData = {
              ...updatedFormData,
              ...parsedLocalDb,
              lineTemplate: takeoff.lineTemplate,
            };
          }
        } catch (err) {
          console.warn("Error parseando lineTemplate:", err);
        }
      }
      const current_selected_perimeter = takeoff?.perimetro ?? null;
      const current_selected_name = takeoff?.name  ?? null;

      // //document.getElementById('wall_length').readOnly = false;
      if (current_selected_perimeter != null) {
        
        updatedFormData.perimeter = current_selected_perimeter;
        

        //localStorage.setItem("current_selected_length", null);
        //document.getElementById('wall_length').readOnly = false;
      }
      if (current_selected_name != null) {

        updatedFormData.name = current_selected_name;
        //localStorage.setItem("takeoff_name", null);
      }
      if (Array.isArray(updatedFormData.perimeterFields)) {
        updatedFormData.perimeterFields = updatedFormData.perimeterFields.map((f) => ({
          ...f,
          perimeter: current_selected_perimeter || f.perimeter || "",
        }));
      }
      setFormDataPerimeter(updatedFormData);
      CalculateData(updatedFormData);


    })();
  }, []);

  // Add a new row for perimeter fields
  const handleAddClick = () => {
    setFormDataPerimeter({
      ...formDataPerimeter,
      perimeterFields: [
        ...formDataPerimeter.perimeterFields,
        { perimeter: takeoff?.perimetro ?? "", material: "", materialQty: "", totalLf: "", totalUnits: "" }
      ]
    });
  };

  // Delete a row from the perimeter fields
  const handleDeleteClick = (index) => {
    const updatedPerimeterFields = [...formDataPerimeter.perimeterFields];
    updatedPerimeterFields.splice(index, 1);
    setFormDataPerimeter({ ...formDataPerimeter, perimeterFields: updatedPerimeterFields });
  };

  // Calculate and send the form data to the server
  const CalculateData = async (updatedFormData) => {
    const dataToSend = {
      template_name: formDataPerimeter.name,
      trade_name: formDataPerimeter.trade,
      formData: updatedFormData,
      type: "perimeter",
      projectId: projectId,
    };
    console.log(dataToSend);

    const response = await fetch(`/api/CalculateData`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${routes.__token}`,
      },
      body: JSON.stringify(dataToSend),
    }).catch(function (error) {
      console.log("Request failed", error);
    });

    const data = await response.json();

    if (data.status === 200) {
      document.getElementById("totales_div").innerHTML = data.resultado.totales_html;
      setFormDataPerimeter(data.resultado);
    }
    if (data.status === 400) {
      toast.error("Calculation error!", {
        position: "top-right",
        autoClose: 5000,
        hideProgressBar: false,
        closeOnClick: true,
        pauseOnHover: true,
        draggable: true,
        progress: 0,
      });
    }
    if (!response.ok) {
      throw new Error("Error processing");
    }
  };

  // Handle form submission
  /*const handleFormSubmit = () => {
    // Save form data to local storage
    //localStorage.setItem("savedFormDataPerimeter", JSON.stringify(formDataPerimeter));
    //const savedData = localStorage.getItem("savedFormDataPerimeter");

    if (savedData === JSON.stringify(formDataPerimeter)) {
      toast.success("Data Saved Successfully!", {
        position: "top-right",
        autoClose: 5000,
        hideProgressBar: false,
        closeOnClick: true,
        pauseOnHover: true,
        draggable: true,
        progress: 0,
      });
    } else {
      toast.warning("Something went wrong. Please, try again!", {
        position: "top-right",
        autoClose: 5000,
        hideProgressBar: false,
        closeOnClick: true,
        pauseOnHover: true,
        draggable: true,
        progress: 0,
      });
    }

    CalculateData(formDataPerimeter);

    setDisplay(false);
  };*/

  const handleFormSubmit = async (e) => {
    e.preventDefault();
    try {
      const perimeterName = formDataPerimeter.name || "Perimeter Takeoff";

      await db.line_Takeoff.clear(); // igual que length
      await db.line_Takeoff.add({
        takeoff_name: perimeterName,
        lineTemplate: JSON.stringify(formDataPerimeter),
        updated_at: new Date().toISOString(),
      });

      toast.success("Perimeter Takeoff guardado en Dexie!", toastOptions);
      setDisplay(false);
    } catch (err) {
      console.error("Error guardando Perimeter en Dexie:", err);
      toast.error("No se pudo guardar el Perimeter Takeoff", toastOptions);
    }
  };

  const handleSaveTemplate = async () => {
    try {
      setLoading(true);
      setLoadingMesagge("Saving template...");
      const dataToSend = {
        template_name: formDataPerimeter.name,
        trade_name: formDataPerimeter.trade,
        formData: formDataPerimeter,
        template_type: 'perimeter',
      };
      if (!formDataPerimeter.name) {
        toast.error("Please enter a TakeOff name.");
        setLoading(false);
        return;
      }
      const response = await fetch(`/api/save-line-template`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${routes.__token}`,
        },
        body: JSON.stringify(dataToSend),
      });
      const data = await response.json();
      if (data.status === 200) {
        // HTTP status code in the range 200-299
        toast.success("Template added Successfully!", { ...toastOptions });
        signal.emit("template.created", {
          template_name: formDataPerimeter.takeoff_name,
          template_type: "perimeter"
        });
        setTimeout(() => {
          setDisplay(false);
        }, 500);
      }
      if (data.status === 400) {
        // HTTP status code 400
        toast.error("Template already exists!", { ...toastOptions });
      }
      if (!response.ok) {
        throw new Error("Error saving as template");
      }
      // console.log("formData", formData);
    } catch (error) {
      console.error("Error saving template:", error);
      toast.error("Error saving template, please try again.");
    } finally {
      setLoading(false);
    }
  };

  // Fetch wall materials and trade data
  useEffect(() => {
    const fetchWallMaterials = async () => {
      try {
        const response = await fetch(`/api/materials/${projectId}`, {
          method: "GET",
          headers: {
            Authorization: `Bearer ${routes.__token}`,
          },
        });

        if (!response.ok) {
          return;
        }

        const data = await response.json();
        setWallMaterials(data);
      } catch (error) {
        console.error("Error fetching wall materials data:", error);
      }
    };

    const fetchTradeData = async () => {
      try {
        const response = await fetch("/api/materials/divisions", {
          method: "GET",
          headers: {
            Authorization: `Bearer ${routes.__token}`,
          },
        });

        if (!response.ok) {
          return;
        }

        const data = await response.json();
        setTrade(data);
      } catch (error) {
        console.error("Error fetching trade data:", error);
      }
    };

    fetchWallMaterials();
    fetchTradeData();
  }, []);

  return (
    <>
      <ProcessingOverlay visible={loading} message={loadingMesagge} />
      {createPortal(
        <Draggable>
          <div className="popup__count">
            <div className="modal-header">
              Perimeter Takeoff
              <span className="close-btn" onClick={() => setDisplay(false)}>&times;</span>
            </div>
            <form className="modal-body">
              <label className="label">Select Template</label>
              <select 
                name="lineTemplate"
                value={formDataPerimeter.lineTemplate}
                onChange={set_line_template}>
                <option value="" hidden>
                  -- Select template --
                </option>
                {templates.map((t) => (
                  <option key={t.id} value={JSON.stringify(t)}>
                    {t.template_name}
                  </option>
                ))}
              </select>

              <label className="label">Takeoff Name</label>
              <input
                type="text"
                placeholder="Takeoff Name"
                name="name"
                id="name"
                value={formDataPerimeter.name}
                onChange={handleInputChange}
                onBlur={handleInputBlur}
              />

              <label className="label">Select Trade</label>
              <select
                name="trade"
                value={formDataPerimeter.trade}
                onChange={handleInputChange}
              >
                <option value="" hidden="">
                  -- Select Trade --
                </option>
                {trade.map((tradeItem) => (
                  <option key={tradeItem.id} value={JSON.stringify(tradeItem)}>
                    {tradeItem.name}
                  </option>
                ))}
              </select>

              <label className="label text-center fw-bold">Perimeter Lineal ft</label>
              {formDataPerimeter.perimeterFields.map((field, index) => (
                <div key={index} className="form-row my-2">
                  <input
                    type="number"
                    step="0.0001"
                    name={`perimeterFields[${index}][perimeter]`}
                    value={field.perimeter}
                    placeholder="Perimeter Lineal ft"
                    onChange={handleInputChange}
                    onBlur={handleInputBlur}
                    className="perimetro"
                    readOnly={!!takeoff?.perimetro}
                  />
                  <select
                    name={`perimeterFields[${index}][material]`}
                    value={field.material}
                    onChange={handleInputChange}
                  >
                    <option value="" hidden>-- Select Material --</option>
                    {wallMaterials.map((material) => (
                      <option key={material.id} value={JSON.stringify(material)}>{material.name}</option>
                    ))}
                  </select>
                  <input
                    type="number"
                    step="0.0001"
                    name={`perimeterFields[${index}][materialQty]`}
                    value={field.materialQty}
                    placeholder="Materials Quantity"
                    onChange={handleInputChange}
                    onBlur={handleInputBlur}
                  />
                  {/* <input
                    type="number"
                    step="0.0001"
                    name={`perimeterFields[${index}][totalLf]`}
                    value={field.totalLf}
                    placeholder="Total Lf"
                    readOnly
                    onChange={handleInputChange}
                  /> */}
                  <input
                    type="number"
                    step="0.0001"
                    name={`perimeterFields[${index}][totalUnits]`}
                    value={field.totalUnits}
                    placeholder="Total Units"
                    readOnly
                    //onChange={handleInputChange}
                  />
                  {formDataPerimeter.perimeterFields.length > 1 && (
                    <button
                      className="btn btn-danger mr-2"
                      type="button"
                      onClick={() => handleDeleteClick(index)}
                    >
                      <i className="fa-solid fa-trash" />
                    </button>
                  )}
                </div>
              ))}

              <button className="btn btn-primary mr-2" type="button" onClick={handleAddClick}>
                Add More Fields
              </button>
              <div name="totales_div" id="totales_div">tabla totales</div>
              <label className="label">Notes</label>
              <textarea
                name="note"
                rows={10}
                value={formDataPerimeter.note}
                onChange={handleInputChange}
              />
              <button
                    className="btn-save mt-2"
                    onClick={handleSaveTemplate}
                    type="button"
                  >
                    Save as Template
              </button>
            </form>
          </div>
        </Draggable>,
      document.querySelector("#root")
    )}
    </>
  );
}

export default PerimeterPopup;
