import { useEffect, useState } from 'react';
import { useLocation } from "react-router-dom";
import { db } from "../database/db";
import { useLiveQuery } from "dexie-react-hooks";
import PerimeterPopup from "./PerimeterPopup"; // Importa el popup de perímetro
import PerimeterRowContext from './PerimeterRowContext';
import { projectId } from "../Constants";
import { routes } from "../Constants";
import "../Css/rightbar.css";

function PerimeterTable({ data, setDetails }) {
    const [context, setContext] = useState(null);
    const [openPerimeterPopup, setOpenPerimeterPopup] = useState(false); // Estado para abrir el popup de perímetro
    const [perimeterData, setPerimeterData] = useState(null); // Estado para almacenar los datos del perímetro seleccionado
    const { pathname } = useLocation();
    const [dataTakeoff, setDataTakeoff] = useState();



    const current_selected_length = (state, perimetro, name, template) => {
        /*localStorage.setItem("current_selected_length", length);
        localStorage.setItem("takeoff_name", name);
        localStorage.setItem("lineTemplate", lineTemplate);
        // console.log(lineTemplate,lineTemplate)
        console.log("length "+length);*/
        const data = {
                    name: name,
                    perimetro: perimetro,
                    lineTemplate: JSON.parse(template),
                };

        setDataTakeoff(data);
         
        //localStorage.setItem("lineTemplate",null); 
        //localStorage.setItem("current_selected_length",null); 
        // localStorage.setItem("takeoff_name",null); 

        ObtenData(projectId, name,perimetro)

    }


    const ObtenData = async (projectId, name,perimetro) => {
        const dataToSend = {
            // template_name: name,
            trade_name: name,
            // formData: updatedFormData,
            projectId: projectId,
        };
        const response = await fetch(`/api/ObtenData`, {
            method: "POST",
            headers: {
                "Content-Type": "application/json",
                Authorization: `Bearer ${routes.__token}`,
            },
            body: JSON.stringify(dataToSend),
        }).catch(function (error) {                        // catch
            console.log('Request failed', error);
        });;
        const data = await response.json();
        if (data.status === 200) {

            /*if (data.resultado != null) {
                setPerimeterData(data.resultado);
                setPerimeterData({...perimeterData,name:name,PerimeterValue:perimetro});
            }
            else
            {
                setPerimeterData({...perimeterData,name:name,PerimeterValue:perimetro});
            }*/

            let resultado = data.resultado ?? {};
            // agrega name y PerimeterValue al resultado que ya viene completo
            resultado.name = name;
            resultado.PerimeterValue = perimetro;

            setPerimeterData(resultado);

            console.log("👉 Resultado final que se manda al popup:", resultado);
            setOpenPerimeterPopup(true);


        }
        if (data.status === 400) {
            // HTTP status code 400
            //toast.error("calculation error !", { ...toastOptions });
            console.log(data.resultado);
            //setFormData(updatedFormData);
        }
        if (!response.ok) {
            throw new Error("Error proccesning");
        }
        //console.log("proccesing result", data);
    };








    const handleContext = (e, index) => {
        e.preventDefault();
        setDetails(null);
        let { clientX, clientY } = e;
        setContext({ x: clientX, y: clientY, index });
    };

    const Data = useLiveQuery(async () => {
        let drawingData = await db.drawings.where({ path: pathname }).first();
        return drawingData;
    }, [pathname]);

    useEffect(() => {
        let contextEvent = () => {
            setContext(null);
        };
        document.addEventListener('click', contextEvent);
        return () => {
            document.removeEventListener('click', contextEvent);
        };
    }, []);

    // Grouping perimeters by name
    const allPerimeters = data?.perimeter || [];
    const groupedPerimeterData = {};

    allPerimeters.forEach((item) => {
        const name = item.meta.name;
        const template = item.meta.lineTemplate;
        const value1 = item.data[0][1];
        const value2 = item.data[0][2];

        if (groupedPerimeterData[name]) {
            groupedPerimeterData[name].push({
                name: item.meta.name,
                data: item.data,
                value1: value1,
                value2: value2,
                template: template,
                stroke: item.meta.stroke,
            });
        } else {
            groupedPerimeterData[name] = [
                {
                    name: item.meta.name,
                    data: item.data,
                    value1: value1,
                    value2: value2,
                    template: template,
                    stroke: item.meta.stroke,
                },
            ];
        }
    });

    // Calculate the sum of value1 for each group of perimeters
    Object.keys(groupedPerimeterData).forEach((groupName) => {
        const sumValue1 = groupedPerimeterData[groupName].reduce(
            (sum, entry) => sum + entry.value1,
            0
        );
        groupedPerimeterData[groupName].sumValue1 = sumValue1.toFixed(2);

        // Merge the data arrays from the grouped perimeters into a single data array within the group
        const mergedDataArray = groupedPerimeterData[groupName].reduce((mergedData, entry) => {
            return mergedData.concat(entry.data);
        }, []);

        groupedPerimeterData[groupName].data = mergedDataArray;
    });

    const handleMouseInOut = async (e, index, isEntering) => {
        let newPerimeters = [...Data?.perimeter];
        if (newPerimeters[index]) {
            const existingRecord = await db.drawings.where({ path: pathname }).first();
            if (existingRecord) {
                const perimeterItem = existingRecord.perimeter[index];
                if (isEntering) {
                    
                    if (!perimeterItem.meta.originalStroke) {
                        perimeterItem.meta.originalStroke = perimeterItem.meta.stroke;
                        perimeterItem.meta.originalFill = perimeterItem.meta.fill;
                    }

                    perimeterItem.meta.stroke = '#f5ed05';
                    perimeterItem.meta.fill = 'rgba(238, 236, 85, 0.5)';
                } else {
                    // Restauramos el color original
                    perimeterItem.meta.stroke = perimeterItem.meta.originalStroke || 'blue';
                    perimeterItem.meta.fill = perimeterItem.meta.originalFill || 'transparent';
                }
                await db.drawings.where({ path: pathname }).modify({ perimeter: existingRecord.perimeter });
            }
        }
    };

    // Maneja el clic en un perímetro para abrir el popup con los detalles del perímetro
    const handleRowClick = (name, data) => {
        // setPerimeterData({ name, data });
        // setOpenPerimeterPopup(true); // Abre el popup de perímetro con los datos seleccionados
    };

    return (
        <>
            <table className="takeoff-table">
                <tbody>
                    {groupedPerimeterData &&
                        Object.keys(groupedPerimeterData).map((groupName, index) => {
                            return (
                                <tr
                                    key={index}
                                    onContextMenu={(e) => handleContext(e, index)}
                                    onClick={() => handleRowClick(groupName, groupedPerimeterData[groupName].data)} // Llama a la función para abrir el popup
                                    onMouseEnter={(e) => handleMouseInOut(e, index, true)}
                                    onMouseLeave={(e) => handleMouseInOut(e, index, false)}
                                >
                                    <td >
                                        <span 
                                            className="perimeter-preview"
                                            style={{
                                                borderColor: groupedPerimeterData[groupName][0].stroke,
                                            }}
                                        ></span>
                                    </td>
                                    <td className="text-truncate fw-semibold">{groupName}</td>
                                    <td className="text-end">{groupedPerimeterData[groupName].sumValue1}</td>
                                    <td className="text-end">{groupedPerimeterData[groupName][0].value2}</td>
                                    <td className="text-muted">{(groupedPerimeterData[groupName][0].template!=null) ? JSON.parse(groupedPerimeterData[groupName][0].template).template_name : 'None'}</td> 
                                    <td className="text-center"><button
                                        className="btn btn-sm btn-primary px-3"
                                        onClick={() => current_selected_length(true, groupedPerimeterData[groupName].sumValue1, groupName, groupedPerimeterData[groupName][0].template)}>
                                        Details
                                    </button></td>
                                </tr>
                            );
                        })}
                </tbody>
            </table>

            {context ? <PerimeterRowContext details={context} /> : <></>}

            {/* Abre el popup de perímetro si está abierto */}
            {openPerimeterPopup && (
                <PerimeterPopup
                    setDisplay={setOpenPerimeterPopup} // Función para cerrar el popup
                    perimeterData={perimeterData} // Pasa los datos del perímetro seleccionado
                    takeoff={dataTakeoff}
                />
            )}
        </>
    );
}

export default PerimeterTable;
